-- 按名称索引权重
local function gW(name)  return W[name]   end
local function gS(name)  return W["S_" .. name] end

-- ---------- 权重读取工具 ----------
-- 权重字符串里第 i 个字节是补码表示的 INT8
local sbyte = string.byte

local function wget(str, i)
  local b = sbyte(str, i)
  if b >= 128 then b = b - 256 end
  return b
end

-- ---------- 矩阵乘：直接从字符串按需读权重 ----------
local function matvec(str_w, s, xv, yv, o_dim, i_dim)
  for o = 1, o_dim do
    local base = (o - 1) * i_dim
    local acc = 0
    for i = 1, i_dim do
      acc = acc + wget(str_w, base + i) * xv[i]
    end
    yv[o] = acc * s
  end
end

-- ---------- RoPE ----------
local rope_cos, rope_sin
local function rope_init(d_head, max_seq, base)
  local half = math.floor(d_head / 2)
  rope_cos, rope_sin = {}, {}
  for p = 0, max_seq - 1 do
    for i = 1, half do
      local theta = base ^ (-2.0 * (i - 1) / d_head)
      local a = p * theta
      rope_cos[p * half + i] = math.cos(a)
      rope_sin[p * half + i] = math.sin(a)
    end
  end
end

local function rope_apply(vec, base, pos, d_head)
  local half = math.floor(d_head / 2)
  local co = pos * half
  for i = 1, half do
    local c = rope_cos[co + i]
    local s = rope_sin[co + i]
    local i1 = base + i - 1
    local i2 = i1 + half
    local x1 = vec[i1]
    local x2 = vec[i2]
    vec[i1] = x1 * c - x2 * s
    vec[i2] = x1 * s + x2 * c
  end
end

-- ---------- 缓冲区 ----------
local x, xn, q, k, v, ao, proj, ff1, ff2, logits
local scores
local kv_k, kv_v

local function alloc_bufs()
  x, xn, q, k, v, ao, proj, ff2 = {}, {}, {}, {}, {}, {}, {}, {}
  ff1, logits, scores = {}, {}, {}
  for i = 1, D do
    x[i] = 0; xn[i] = 0; q[i] = 0; k[i] = 0; v[i] = 0
    ao[i] = 0; proj[i] = 0; ff2[i] = 0
  end
  for i = 1, FF do ff1[i] = 0 end
  for i = 1, VOCAB_SZ do logits[i] = 0 end
  for i = 1, MS do scores[i] = 0 end

  local kvn = NL * MS * D
  kv_k, kv_v = {}, {}
  for i = 1, kvn do
    kv_k[i] = 0
    kv_v[i] = 0
  end
end

-- ---------- 算子 ----------
local function rmsnorm(vv, g)
  local ss = 0
  for i = 1, D do
    local t = vv[i]; ss = ss + t * t
  end
  local inv = 1 / math.sqrt(ss / D + 1e-6)
  for i = 1, D do vv[i] = vv[i] * inv * g[i] end
end

-- 每一层的权重名用拼接即可，省掉一堆索引表
local function wq_str(L) return W["L" .. L .. "_wq"] end
local function wk_str(L) return W["L" .. L .. "_wk"] end
local function wv_str(L) return W["L" .. L .. "_wv"] end
local function wo_str(L) return W["L" .. L .. "_wo"] end
local function n1_str(L) return W["L" .. L .. "_n1"] end
local function w1_str(L) return W["L" .. L .. "_w1"] end
local function w2_str(L) return W["L" .. L .. "_w2"] end
local function n2_str(L) return W["L" .. L .. "_n2"] end

local function wq_s(L) return W["S_L" .. L .. "_wq"] end
local function wk_s(L) return W["S_L" .. L .. "_wk"] end
local function wv_s(L) return W["S_L" .. L .. "_wv"] end
local function wo_s(L) return W["S_L" .. L .. "_wo"] end
local function n1_s(L) return W["S_L" .. L .. "_n1"] end
local function w1_s(L) return W["S_L" .. L .. "_w1"] end
local function w2_s(L) return W["S_L" .. L .. "_w2"] end
local function n2_s(L) return W["S_L" .. L .. "_n2"] end

-- n1、n2 是 rmsnorm 增益，长度 D，本身就是权重但不是矩阵
-- 这里为了统一，把它们也当字符串读。但为了方便，运行时转成表也可以：
-- 只是 40 个 double，不值得纠结。

-- ---------- 前向 ----------
local function forward_one(token, pos)
  -- emb 查表
  local eb = token * D + 1        -- string.byte 是 1-based
  for i = 1, D do
    x[i] = wget(W.emb, eb + i - 1) * W.S_emb
  end

  for L = 0, NL - 1 do
    -- rmsnorm 增益也按需读
    for i = 1, D do xn[i] = x[i] end
    do
      local ss = 0
      for i = 1, D do
        local t = xn[i]; ss = ss + t * t
      end
      local inv = 1 / math.sqrt(ss / D + 1e-6)
      local gstr = n1_str(L)
      local gs   = n1_s(L)
      for i = 1, D do
        xn[i] = xn[i] * inv * (wget(gstr, i) * gs)
      end
    end

    matvec(wq_str(L), wq_s(L), xn, q, D, D)
    matvec(wk_str(L), wk_s(L), xn, k, D, D)
    matvec(wv_str(L), wv_s(L), xn, v, D, D)

    for hh = 0, H - 1 do
      rope_apply(q, hh * DH + 1, pos, DH)
      rope_apply(k, hh * DH + 1, pos, DH)
    end

    local cb = (L * MS + pos) * D
    for i = 1, D do
      kv_k[cb + i] = k[i]
      kv_v[cb + i] = v[i]
    end

    for hh = 0, H - 1 do
      local qb = hh * DH
      local ab = hh * DH
      local maxs = -1e30
      for t = 0, pos do
        local kb = (L * MS + t) * D + hh * DH
        local s = 0
        for i = 1, DH do
          s = s + q[qb + i] * kv_k[kb + i]
        end
        s = s * INV_SQRT_DH
        scores[t + 1] = s
        if s > maxs then maxs = s end
      end
      local sum = 0
      for t = 1, pos + 1 do
        local e = math.exp(scores[t] - maxs)
        scores[t] = e; sum = sum + e
      end
      local inv_sum = 1 / sum
      for i = 1, DH do ao[ab + i] = 0 end
      for t = 0, pos do
        local w = scores[t + 1] * inv_sum
        local vb = (L * MS + t) * D + hh * DH
        for i = 1, DH do
          ao[ab + i] = ao[ab + i] + w * kv_v[vb + i]
        end
      end
    end

    matvec(wo_str(L), wo_s(L), ao, proj, D, D)
    for i = 1, D do x[i] = x[i] + proj[i] end

    for i = 1, D do xn[i] = x[i] end
    do
      local ss = 0
      for i = 1, D do
        local t = xn[i]; ss = ss + t * t
      end
      local inv = 1 / math.sqrt(ss / D + 1e-6)
      local gstr = n2_str(L)
      local gs   = n2_s(L)
      for i = 1, D do
        xn[i] = xn[i] * inv * (wget(gstr, i) * gs)
      end
    end

    matvec(w1_str(L), w1_s(L), xn, ff1, FF, D)
    for i = 1, FF do
      local xx = ff1[i]
      ff1[i] = 0.5 * xx * (1 + math.tanh(0.7978845608 * (xx + 0.044715 * xx * xx * xx)))
    end
    matvec(w2_str(L), w2_s(L), ff1, ff2, D, FF)
    for i = 1, D do x[i] = x[i] + ff2[i] end
  end

  -- 最终 rmsnorm
  do
    local ss = 0
    for i = 1, D do
      local t = x[i]; ss = ss + t * t
    end
    local inv = 1 / math.sqrt(ss / D + 1e-6)
    local nf_str = W.nf
    local nf_s   = W.S_nf
    for i = 1, D do
      x[i] = x[i] * inv * (wget(nf_str, i) * nf_s)
    end
  end

  -- 输出投影（权重共享 emb）
  for vv = 1, VOCAB_SZ do
    local eb2 = (vv - 1) * D + 1
    local s = 0
    for i = 1, D do
      s = s + wget(W.emb, eb2 + i - 1) * W.S_emb * x[i]
    end
    logits[vv] = s
  end
end

-- ---------- 采样 ----------
local function sample_token(n, history, hist_len, rep_penalty)
  local adjusted = {}
  for i = 1, n do adjusted[i] = logits[i] end

  if hist_len >= 3 then
    local b0 = history[hist_len - 2]
    local b1 = history[hist_len - 1]
    local b2 = history[hist_len]
    local repeated = false
    for i = 1, hist_len - 3 do
      if history[i] == b0 and history[i + 1] == b1 and history[i + 2] == b2 then
        repeated = true; break
      end
    end
    if repeated then
      adjusted[b0 + 1] = adjusted[b0 + 1] - rep_penalty
      adjusted[b1 + 1] = adjusted[b1 + 1] - rep_penalty
      adjusted[b2 + 1] = adjusted[b2 + 1] - rep_penalty
    end
  end

  local best = 1
  local bestv = adjusted[1]
  for i = 2, n do
    if adjusted[i] > bestv then bestv = adjusted[i]; best = i end
  end
  return best - 1
end

-- ---------- 生成 ----------
local function generate(prompt, plen, max_new, out)
  for i = 1, NL * MS * D do
    kv_k[i] = 0; kv_v[i] = 0
  end

  local pos = 0
  for i = 1, plen do
    if pos >= MS then break end
    forward_one(prompt[i], pos); pos = pos + 1
  end

  local history, hist_len, out_len = {}, 0, 0
  for s = 1, max_new do
    if pos >= MS then break end
    local nxt = sample_token(VOCAB_SZ, history, hist_len, 5.0)
    out_len = out_len + 1
    out[out_len] = nxt
    hist_len = hist_len + 1
    history[hist_len] = nxt
    if nxt == 10 then break end
    forward_one(nxt, pos)
    pos = pos + 1
    coroutine.yield()
  end
  return out_len
end

-- ============================================================
--  界面状态
-- ============================================================
local ctx = {}
local input_str = ""
local scroll = 0
local render_lines = {}
local render_dirty = true
local gen_co, gen_out = nil, nil
local busy = false
local lineH = 14
local visLines = 10
local input_pending = {}
local pending_need  = 0

-- UTF-8 工具
local function utf8_need_bytes(c)
  if c < 0x80 then return 1
  elseif c < 0xC0 then return 1
  elseif c < 0xE0 then return 2
  elseif c < 0xF0 then return 3
  else return 4 end
end
local function utf8_chars(s)
  local t = {}; local i, n = 1, #s
  while i <= n do
    local c = string.byte(s, i); local len = 1
    if c < 0x80 then len = 1
    elseif c < 0xE0 then len = 2
    elseif c < 0xF0 then len = 3 else len = 4 end
    t[#t + 1] = string.sub(s, i, i + len - 1); i = i + len
  end
  return t
end
local function utf8_remove_last(s)
  local n = #s; if n == 0 then return s end
  local i = n
  while i >= 1 do
    local b = string.byte(s, i)
    if b >= 0x80 and b < 0xC0 then i = i - 1 else break end
  end
  return string.sub(s, 1, i - 1)
end
local function str_to_bytes(s)
  local t = {}; for i = 1, #s do t[i] = string.byte(s, i) end; return t
end
local function bytes_to_str(t, n)
  local c = {}; for i = 1, n do c[i] = string.char(t[i]) end
  return table.concat(c)
end
local function split_newlines(s)
  local parts = {}; local start = 1
  while true do
    local i = string.find(s, "\n", start, true)
    if not i then parts[#parts + 1] = string.sub(s, start); break end
    parts[#parts + 1] = string.sub(s, start, i - 1); start = i + 1
  end
  return parts
end
local function safe_setFont(gc)
  local ok = pcall(gc.setFont, gc, "sansserif", "r", 9)
  if not ok then pcall(gc.setFont, gc, "serif", "r", 9) end
end
local function wrap_msg(gc, prefix, text, maxw)
  local pw = gc:getStringWidth(prefix)
  local sw = gc:getStringWidth(" ")
  local nspace = 0
  if sw > 0 then nspace = math.floor(pw / sw + 0.5) end
  local indent = string.rep(" ", nspace)
  local iw = gc:getStringWidth(indent)
  local out = {}
  local paras = split_newlines(text)
  for pi = 1, #paras do
    local chars = utf8_chars(paras[pi])
    local cur = (pi == 1) and prefix or indent
    local cw = (pi == 1) and pw or iw
    if #chars == 0 then
      out[#out + 1] = cur
    else
      for i = 1, #chars do
        local w = gc:getStringWidth(chars[i])
        if cw + w > maxw and #cur > 0 then
          out[#out + 1] = cur; cur = indent; cw = iw
        end
        cur = cur .. chars[i]; cw = cw + w
      end
      out[#out + 1] = cur
    end
  end
  if #out == 0 then out[1] = prefix end
  return out
end
local function rebuild_lines(gc, maxw)
  safe_setFont(gc)
  render_lines = {}
  if #ctx == 0 then
    render_lines[1] = { text = "输入内容后按 Enter 发送。", role = "info" }
    return
  end
  for ci = 1, #ctx do
    local e = ctx[ci]
    local prefix = (e.role == "user") and "> " or "AI: "
    local wrapped = wrap_msg(gc, prefix, e.text, maxw)
    for wi = 1, #wrapped do
      render_lines[#render_lines + 1] = { text = wrapped[wi], role = e.role }
    end
  end
end
local function start_generate(user_text)
  local prompt = { 0x01 }
  local bs = str_to_bytes(user_text)
  for i = 1, #bs do prompt[#prompt + 1] = bs[i] end
  prompt[#prompt + 1] = 0x0A
  prompt[#prompt + 1] = 0x02
  gen_out = {}
  gen_co = coroutine.create(function()
    return generate(prompt, #prompt, 120, gen_out)
  end)
  busy = true
  timer.start(0.05)
end

-- ============================================================
--  初始化
-- ============================================================
rope_init(DH, MS, 10000.0)
alloc_bufs()
local g_ok = true

toolpalette.register({
  { "对话",
    { "清空上下文", function()
        ctx = {}; scroll = 0; render_dirty = true
        platform.window:invalidate()
      end
    },
    { "粘贴剪贴板", function()
        local t = clipboard.getText()
        if t and #t > 0 then
          t = t:gsub("[\r\n\t]", " ")
          input_str = input_str .. t
          render_dirty = true
          platform.window:invalidate()
        end
      end
    }
  }
})

-- ============================================================
--  事件
-- ============================================================
function on.resize(w, h)
  render_dirty = true
  platform.window:invalidate()
end
function on.activate() platform.window:invalidate() end

function on.paint(gc)
  local W2 = platform.window:width()
  local H2 = platform.window:height()
  gc:setColorRGB(0xFFFFFF); gc:fillRect(0, 0, W2, H2)
  safe_setFont(gc)
  lineH = gc:getStringHeight("Ag")
  if not lineH or lineH < 10 then lineH = 12 end
  local inpH = lineH + 6
  local histH = H2 - inpH - 4
  visLines = math.floor(histH / lineH)
  if visLines < 1 then visLines = 1 end
  if render_dirty then rebuild_lines(gc, W2 - 8); render_dirty = false end

  gc:setColorRGB(0xCC0000)
  gc:drawString("g_ok=" .. tostring(g_ok), 4, H2 - inpH - 18, "top")

  local total = #render_lines
  local maxScroll = total - visLines
  if maxScroll < 0 then maxScroll = 0 end
  if scroll > maxScroll then scroll = maxScroll end
  if scroll < 0 then scroll = 0 end
  local startIdx = total - visLines - scroll + 1
  if startIdx < 1 then startIdx = 1 end
  local endIdx = startIdx + visLines - 1
  if endIdx > total then endIdx = total end

  local y = 2
  for i = startIdx, endIdx do
    local ln = render_lines[i]
    if ln.role == "user" then gc:setColorRGB(0x1A3F8C)
    elseif ln.role == "ai" then gc:setColorRGB(0x146B3A)
    else gc:setColorRGB(0x666666) end
    gc:drawString(ln.text, 4, y, "top")
    y = y + lineH
  end

  gc:setColorRGB(0x202020); gc:fillRect(0, H2 - inpH, W2, inpH)
  gc:setColorRGB(0xFFFFFF)
  local caret = busy and " ..." or "_"
  gc:drawString("> " .. input_str .. caret, 4, H2 - inpH + 3, "top")
end

function on.charIn(ch)
  local c = string.byte(ch, 1); if not c then return end
  if pending_need == 0 then
    local need = utf8_need_bytes(c)
    if need == 1 then
      input_str = input_str .. ch
      platform.window:invalidate(); return
    end
    input_pending = { c }; pending_need = need - 1
  else
    input_pending[#input_pending + 1] = c
    pending_need = pending_need - 1
    if pending_need == 0 then
      local t = {}
      for i = 1, #input_pending do t[i] = string.char(input_pending[i]) end
      input_str = input_str .. table.concat(t)
      input_pending = {}
    end
  end
  platform.window:invalidate()
end

function on.backspaceKey()
  if pending_need > 0 then
    input_pending = {}; pending_need = 0
  else
    input_str = utf8_remove_last(input_str)
  end
  platform.window:invalidate()
end

function on.escapeKey()
  input_str = ""; input_pending = {}; pending_need = 0
  platform.window:invalidate()
end

function on.enterKey()
  if busy then return end
  if #input_str == 0 then return end
  ctx[#ctx + 1] = { role = "user", text = input_str }
  local u = input_str
  input_str = ""; input_pending = {}; pending_need = 0
  scroll = 0; render_dirty = true
  platform.window:invalidate()
  start_generate(u)
end

function on.arrowUp() scroll = scroll + 3; platform.window:invalidate() end
function on.arrowDown()
  scroll = scroll - 3
  if scroll < 0 then scroll = 0 end
  platform.window:invalidate()
end

function on.timer()
  if not gen_co then timer.stop(); return end
  local ok, n = coroutine.resume(gen_co)
  if coroutine.status(gen_co) == "dead" then
    gen_co = nil; timer.stop(); busy = false
    if ok and n and n > 0 then
      ctx[#ctx + 1] = { role = "ai", text = bytes_to_str(gen_out, n) }
    else
      ctx[#ctx + 1] = { role = "ai", text = "(无输出)" }
    end
    scroll = 0; render_dirty = true
  end
  platform.window:invalidate()
end